{
  "name": "Wasatch 拉曼演示程序",
  "name_en": "Wasatch Raman Demo Application",
  "manufacturer": "",
  "description": "用于拉曼实验演示的非物理软件组件。它负责解析命令行参数、连接激光驱动板与 IDS 相机，并在运行循环中协调采集光谱或图像、按需触发激光以及保存数据文件与 PNG 结果。",
  "description_en": "A non-physical software component for Raman experiment demonstration. It parses command-line arguments, connects to a laser driver board and an IDS camera, and coordinates spectrum or image acquisition in a run loop, optionally firing the laser and saving data files and PNG outputs.",
  "actions": [
    {
      "action_name": "auto-parse_args",
      "description": "解析演示程序的运行参数与采集选项。",
      "description_en": "Parse the demo application's runtime parameters and acquisition options."
    },
    {
      "action_name": "auto-connect",
      "description": "连接激光驱动板与 IDS 相机，并同步激发波长等信息以支持波数计算。",
      "description_en": "Connect to the laser driver board and IDS camera, and synchronize excitation wavelength information to support wavenumber calculation."
    },
    {
      "action_name": "auto-run",
      "description": "运行采集循环，读取光谱或图像、按需触发激光，并保存数据与图像结果。",
      "description_en": "Run the acquisition loop to read spectra or images, trigger the laser as needed, and save data and image outputs."
    }
  ],
  "tag_hints": [
    "Raman spectroscopy",
    "demo application",
    "IDS camera",
    "laser control",
    "spectral acquisition",
    "image capture",
    "data logging"
  ]
}

